//! Static route table and request routing. Pure logic, no I/O.

/// A prebuilt response body with its content type.
pub struct Page {
    pub content_type: &'static str,
    pub body: &'static [u8],
}

// Generated by build.rs: `PAGES` (sorted by path) and `NOT_FOUND`.
include!(concat!(env!("OUT_DIR"), "/site.rs"));

static NOT_ALLOWED: Page = Page {
    content_type: "text/plain; charset=utf-8",
    body: b"405 Method Not Allowed\n",
};

/// Old URLs that now live elsewhere: (from, to).
static REDIRECTS: &[(&str, &str)] = &[("/posts", "/")];

/// Request methods we distinguish.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Method {
    Get,
    Head,
    Other,
}

/// What to send back. HEAD bodies are dropped by tiny_http itself.
#[derive(Debug, PartialEq, Eq)]
pub enum Reply {
    Ok(&'static Page),
    /// Permanent redirect to this location.
    Redirect(&'static str),
    NotFound(&'static Page),
    MethodNotAllowed(&'static Page),
}

impl std::fmt::Debug for Page {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Page")
            .field("content_type", &self.content_type)
            .field("len", &self.body.len())
            .finish()
    }
}

impl PartialEq for Page {
    fn eq(&self, other: &Self) -> bool {
        std::ptr::eq(self, other)
    }
}
impl Eq for Page {}

/// Route a request. Query strings are ignored.
pub fn route(method: Method, url: &str) -> Reply {
    if method == Method::Other {
        return Reply::MethodNotAllowed(&NOT_ALLOWED);
    }
    let path = url.split_once('?').map_or(url, |(p, _)| p);
    if let Ok(i) = PAGES.binary_search_by(|(p, _)| (*p).cmp(path)) {
        return Reply::Ok(&PAGES[i].1);
    }
    match REDIRECTS.iter().find(|(from, _)| *from == path) {
        Some((_, to)) => Reply::Redirect(to),
        None => Reply::NotFound(&NOT_FOUND),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn page(path: &str) -> &'static Page {
        &PAGES.iter().find(|(p, _)| *p == path).unwrap().1
    }

    #[test]
    fn table_is_sorted_and_unique() {
        assert!(PAGES.windows(2).all(|w| w[0].0 < w[1].0));
    }

    #[test]
    fn generated_pages_route() {
        assert_eq!(route(Method::Get, "/"), Reply::Ok(page("/")));
        assert!(
            page("/feed.xml")
                .content_type
                .starts_with("application/atom+xml")
        );
        let posts: Vec<_> = PAGES
            .iter()
            .filter(|(p, _)| p.starts_with("/posts/"))
            .collect();
        assert!(!posts.is_empty());
        for (path, pg) in posts {
            assert_eq!(route(Method::Get, path), Reply::Ok(pg));
            assert!(pg.content_type.starts_with("text/html"));
        }
        // Every page in the table is reachable and non-empty.
        for (path, pg) in PAGES {
            assert_eq!(route(Method::Get, path), Reply::Ok(pg), "{path}");
            assert!(!pg.body.is_empty(), "{path}");
        }
    }

    #[test]
    fn query_is_ignored() {
        assert_eq!(route(Method::Get, "/?x=1"), Reply::Ok(page("/")));
        assert_eq!(
            route(Method::Get, "/feed.xml?"),
            Reply::Ok(page("/feed.xml"))
        );
    }

    #[test]
    fn head_routes_like_get() {
        assert_eq!(route(Method::Head, "/"), Reply::Ok(page("/")));
        assert_eq!(route(Method::Head, "/nope"), Reply::NotFound(&NOT_FOUND));
    }

    #[test]
    fn posts_redirects_to_index() {
        assert_eq!(route(Method::Get, "/posts"), Reply::Redirect("/"));
        assert_eq!(route(Method::Head, "/posts?a"), Reply::Redirect("/"));
    }

    #[test]
    fn unknown_is_404() {
        for url in [
            "/nope",
            "",
            "/posts/",
            "/posts/nope",
            "//",
            "/FEED.XML",
            "feed.xml",
            "*",
            "/posts/../",
        ] {
            assert_eq!(
                route(Method::Get, url),
                Reply::NotFound(&NOT_FOUND),
                "{url}"
            );
        }
        assert!(NOT_FOUND.content_type.starts_with("text/html"));
    }

    #[test]
    fn other_methods_are_405() {
        for url in ["/", "/nope", "/posts"] {
            assert_eq!(
                route(Method::Other, url),
                Reply::MethodNotAllowed(&NOT_ALLOWED)
            );
        }
    }
}
